import { ChangeDetectionStrategy, Component } from "@angular/core";
import { CardComponent } from "../../lib/card.component";
import { FancyPillComponent } from "../../lib/fancy-pill.component";
import { PillLegacyComponent } from "../../lib/pill-legacy.component";
import { PillComponent, type PillVariant } from "../../lib/pill.component";

@Component({
    selector: "app-feature-48",
    changeDetection: ChangeDetectionStrategy.OnPush,
    imports: [ PillComponent, FancyPillComponent, CardComponent, PillLegacyComponent ],
    template: `
        <app-card heading="Feature 48" [disableTooltip]="true">
            <div class="row">
                <app-pill label="Info" variant="info" hideHint /><app-pill label="Active" variant="success" hideHint />
                <app-pill-legacy [label]="title" [variant]="statusVariant" [disableTooltip]="count > 3" />
            </div>
            <app-pill [label]="title" hideHint />
            <app-fancy-pill label="Fancy" icon="star" [hideHint]="!isActive" />
        </app-card>
        <app-card heading="Screen flag" [disableTooltip]="disableTooltip" />
    `
})
export class Feature048Component {
    isActive = true;
    count = 6;
    title = "Title 48";
    statusVariant: PillVariant = "warning";
    disableTooltip = false;
}

